class VPT2Tests(TestCase):

    @classmethod
    def setUpClass(cls) -> None:
        np.set_printoptions(linewidth=int(100000000.0))

    @validationTest
    def test_NH3Units(self):
        tag = 'NH3 Internals'
        file_name = 'nh3.fchk'
        _ = -1
        zmatrix = [[0, _, _, _], [1, 0, _, _], [2, 0, 1, _], [3, 0, 1, 2]]

        def conv(r, t, f, **kwargs):
            cp1 = np.cos(f[..., 3])
            ct1 = np.cos(t[..., 2])
            ct2 = np.cos(t[..., 3])
            st1 = np.sin(t[..., 2])
            st2 = np.sin(t[..., 3])
            f[..., 3] = np.arccos(st1 * st2 * cp1 + ct1 * ct2)
            return np.array([r, t, f])

        def inv(r, t, f, **kwargs):
            cp1 = np.cos(f[..., 3])
            ct1 = np.cos(t[..., 2])
            ct2 = np.cos(t[..., 3])
            st1 = np.sin(t[..., 2])
            st2 = np.sin(t[..., 3])
            f[..., 3] = np.arccos((cp1 - ct1 * ct2) / (st1 * st2))
            return np.array([r, t, f])
        file = TestManager.test_data(file_name)
        print('Cart:')
        VPTAnalyzer.run_VPT(file, 2).print_output_tables()
